export default async function install(app){const host=document.getElementById('app-widget-host-place-search');app.assert(host?.shadowRoot,'Search wrapper is missing');const previous={expanded:host.expanded,autoCollapse:host.autoCollapse};const style=document.createElement('style');style.textContent='.toggle {visibility:hidden!important;pointer-events:none!important;}';host.shadowRoot.append(style);const keepOpen=()=>{if(!host.expanded)host.expanded=true;if(host.autoCollapse)host.autoCollapse=false;};const observer=new MutationObserver(keepOpen);app.onCleanup(()=>{observer.disconnect();style.remove();host.expanded=previous.expanded;host.autoCollapse=previous.autoCollapse;});observer.observe(host,{attributes:true,attributeFilter:['expanded','auto-collapse']});keepOpen();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const alignment=app.actions.has('inspect-search-bar')?await app.actions.invoke('inspect-search-bar'):null;const search=document.getElementById('app-widget-place-search'),rect=search.getBoundingClientRect();return {expanded:host.expanded,autoCollapse:host.autoCollapse,toggleVisibility:getComputedStyle(host.shadowRoot.querySelector('.toggle')).visibility,searchWidth:rect.width,searchHeight:rect.height,alignment};}